import java.util.*;

/**
 * Teaching demo: table-less transactional outbox (the SeatGeek / Debezium pattern).
 *
 * Part 1 shows why a dual write breaks: the state is committed in the database
 * and the event is published by a separate call, so a crash between the two
 * leaves one without the other.
 * Part 2 shows the fix: inside ONE database transaction the app updates the
 * business row and emits the event with pg_logical_emit_message, so the WAL
 * entry and the state land in the same COMMIT. The pipeline is at-least-once
 * (a connector crash replays the WAL), so the consumer deduplicates.
 *
 * Deterministic: no threads, no clock, no randomness.
 */
public class OutboxSim {
    static int passed = 0, failed = 0;

    static void check(String name, boolean cond, String detail) {
        System.out.println((cond ? "PASS " : "FAIL ") + name + " -- " + detail);
        if (cond) passed++; else failed++;
    }

    // ---------- the database: one business table, plus the WAL ----------
    static class Db {
        final Map<String, String> business = new LinkedHashMap<>(); // the ONLY table
        final List<String> wal = new ArrayList<>();                  // logical decoding stream
        final List<Integer> lsns = new ArrayList<>();               // absolute LSN per record
        List<String> pending = null;
        Map<String, String> pendingBusiness = null;

        void begin() {
            pending = new ArrayList<>();
            pendingBusiness = new LinkedHashMap<>();
        }

        void update(String key, String value) {
            pendingBusiness.put(key, value);
        }

        void emit(String prefix, String event) {
            pending.add(prefix + "|" + event);
        }

        void commit() {
            business.putAll(pendingBusiness);
            for (String message : pending) {
                wal.add(message);
                lsns.add(lsns.size() + wal.size() - pending.size());
            }
            pending = null;
            pendingBusiness = null;
        }

        void rollback() {
            pending = null;
            pendingBusiness = null;
        }

        // WAL records already acknowledged by the replication slot may be discarded
        void truncateUpTo(int slotLsn) {
            while (!lsns.isEmpty() && lsns.get(0) < slotLsn) {
                lsns.remove(0);
                wal.remove(0);
            }
        }

        int tableCount() {
            return 1; // business table only: no outbox table exists
        }
    }

    // ---------- the connector: Debezium tailing the WAL ----------
    static class Connector {
        final Db db;
        final List<String> broker = new ArrayList<>(); // Kafka side
        final Set<Integer> published = new HashSet<>(); // in-memory marks, lost on crash
        int slotLsn = 0;                               // replication slot: acknowledged records
        boolean crashed = false;

        Connector(Db db) {
            this.db = db;
        }

        // Debezium reads every record after the slot and publishes it
        void pollAndPublish() {
            if (crashed) return;
            for (int i = 0; i < db.wal.size(); i++) {
                int lsn = db.lsns.get(i);
                if (lsn < slotLsn || published.contains(lsn)) continue;
                broker.add(db.wal.get(i));
                published.add(lsn);
            }
        }

        // the acknowledgement that advances the slot
        void ack() {
            int max = slotLsn - 1;
            for (int lsn : published) max = Math.max(max, lsn);
            slotLsn = max + 1;
        }

        // crash between publish and ack: the in-memory marks are gone, the slot is not
        void crashBeforeAck() {
            crashed = true;
            published.clear();
        }

        void restart() {
            crashed = false;
        }

        // Debezium advances the slot with periodic heartbeat-table writes,
        // which is what bounds WAL retention on disk
        void heartbeat() {
            ack();
        }
    }

    // ---------- the consumer: at-least-once delivery, dedup by event id ----------
    static class Consumer {
        final Set<String> seen = new HashSet<>();
        int applied = 0;
        int duplicates = 0;

        void consume(List<String> records) {
            for (String record : records) {
                String eventId = record.substring(record.indexOf('|') + 1);
                if (seen.add(eventId)) applied++;
                else duplicates++;
            }
        }
    }

    public static void main(String[] args) {
        // P1: one COMMIT keeps state and event together
        Db db = new Db();
        db.begin();
        db.update("order-1", "paid");
        db.emit("orders", "evt-1:order-1:paid");
        db.commit();
        check("P1 commit keeps state and event",
                "paid".equals(db.business.get("order-1")) && db.wal.size() == 1,
                "business=paid wal=1");

        // P2: a rollback erases both, so no phantom event exists
        Db db2 = new Db();
        db2.begin();
        db2.update("order-2", "paid");
        db2.emit("orders", "evt-2:order-2:paid");
        db2.rollback();
        check("P2 rollback erases both",
                db2.business.isEmpty() && db2.wal.isEmpty(),
                "business=0 wal=0");

        // P3: connector crash after publish, before ack -> replay -> duplicate delivery
        Db db3 = new Db();
        Connector c3 = new Connector(db3);
        db3.begin();
        db3.update("order-3", "paid");
        db3.emit("orders", "evt-3:order-3:paid");
        db3.commit();
        c3.pollAndPublish();
        c3.crashBeforeAck();
        c3.restart();
        c3.pollAndPublish(); // replay from the slot
        Consumer consumer = new Consumer();
        consumer.consume(c3.broker);
        check("P3 replay duplicates delivery, consumer dedups",
                c3.broker.size() == 2 && consumer.applied == 1 && consumer.duplicates == 1,
                "delivered=" + c3.broker.size() + " applied=" + consumer.applied
                        + " duplicates=" + consumer.duplicates);

        // P4: connector crash before publish -> the WAL still carries the event
        Db db4 = new Db();
        Connector c4 = new Connector(db4);
        db4.begin();
        db4.update("order-4", "paid");
        db4.emit("orders", "evt-4:order-4:paid");
        db4.commit();
        c4.crashBeforeAck();
        c4.restart();
        c4.pollAndPublish();
        Consumer consumer4 = new Consumer();
        consumer4.consume(c4.broker);
        check("P4 crash before publish loses nothing",
                c4.broker.size() == 1 && consumer4.applied == 1,
                "delivered=" + c4.broker.size() + " applied=" + consumer4.applied);

        // P5: there is no outbox table to lock, poll or clean up
        check("P5 no outbox table exists",
                db.tableCount() == 1,
                "tables=1 (business only), no outbox table to lock or clean");

        // P6: heartbeat advances the slot, so WAL retention stays bounded
        Db db6 = new Db();
        Connector c6 = new Connector(db6);
        for (int i = 0; i < 50; i++) {
            db6.begin();
            db6.update("order-" + i, "paid");
            db6.emit("orders", "evt-6-" + i);
            db6.commit();
            c6.pollAndPublish();
            c6.heartbeat();
            db6.truncateUpTo(c6.slotLsn);
        }
        check("P6 heartbeat bounds WAL retention",
                db6.wal.size() == 0,
                "wal records retained=" + db6.wal.size() + " after 50 transactions");

        System.out.println("----");
        System.out.println("checks run=" + (passed + failed) + " passed=" + passed + " failed=" + failed);
    }
}
